<script setup lang="ts">
import {localize} from './localization';

import {computed,ref,watch} from 'vue';
import {useDraftHistory} from './modules/useDraftHistory';
type Point={xMm:number;yMm:number};
const props=withDefaults(defineProps<{rings:Point[][];context:string;language:'zh'|'en';color?:string;disabled?:boolean;topology?:boolean;background?:Point[][];shapePath?:string;backgroundPath?:string;extraBounds?:Point[]}>(),{topology:true}),emit=defineEmits<{update:[rings:Point[][]];select:[ring:number,node:number];cancel:[]}>();
const selected=ref<{ring:number;node:number}>(),viewport=ref('0 0 100 100'),zh=computed(()=>props.language==='zh');
const root=ref<HTMLElement>();
const history=useDraftHistory(()=>props.rings,rings=>emit('update',rings),()=>!!root.value?.getClientRects().length,()=>!!props.disabled);
let drag:{ring:number;node:number;matrix:DOMMatrix;before:Point[][]}|undefined;
watch(()=>props.context,()=>{history.reset();selected.value=undefined;drag=undefined;const points=[...(props.background??[]),...props.rings].flat().concat(props.extraBounds??[]);if(!points.length)return;const xs=points.map(p=>p.xMm),ys=points.map(p=>p.yMm),x=Math.min(...xs),y=Math.min(...ys),w=Math.max(10,Math.max(...xs)-x),h=Math.max(10,Math.max(...ys)-y),pad=Math.max(w,h)*.12;viewport.value=`${x-pad} ${y-pad} ${w+pad*2} ${h+pad*2}`;},{immediate:true});
const path=(rings:Point[][])=>rings.filter(r=>r.length).map(r=>'M '+r.map(p=>`${p.xMm},${p.yMm}`).join(' L ')+' Z').join(' '),radius=computed(()=>Number(viewport.value.split(' ')[2])/90);
function select(ring:number,node:number){selected.value={ring,node};emit('select',ring,node);}
function down(event:PointerEvent,ring:number,node:number){if(props.disabled||event.button!==0)return;const svg=(event.currentTarget as SVGElement).ownerSVGElement,matrix=svg?.getScreenCTM();if(!matrix)return;event.preventDefault();svg!.focus({preventScroll:true});history.begin();select(ring,node);drag={ring,node,matrix:matrix.inverse(),before:structuredClone(props.rings.map(r=>r.map(p=>({...p}))))};svg!.setPointerCapture(event.pointerId);}
function move(event:PointerEvent){if(!drag||props.disabled)return;const p=new DOMPoint(event.clientX,event.clientY).matrixTransform(drag.matrix),rings=props.rings.map(r=>r.map(n=>({...n})));rings[drag.ring][drag.node]={...rings[drag.ring][drag.node],xMm:p.x,yMm:p.y};emit('update',rings);}
function end(event:PointerEvent){if(event.type==='pointercancel'&&drag){drag=undefined;history.rollback();return;}drag=undefined;history.end();}
function insert(){const s=selected.value;if(!s||props.disabled||props.topology===false||props.rings[s.ring].length>=2000)return;const rings=props.rings.map(r=>r.map(p=>({...p}))),ring=rings[s.ring],a=ring[s.node],b=ring[(s.node+1)%ring.length];ring.splice(s.node+1,0,{xMm:(a.xMm+b.xMm)/2,yMm:(a.yMm+b.yMm)/2});emit('update',rings);select(s.ring,s.node+1);}
function remove(){const s=selected.value;if(!s||props.disabled||props.topology===false||props.rings[s.ring].length<=3)return;const rings=props.rings.map(r=>r.map(p=>({...p})));rings[s.ring].splice(s.node,1);emit('update',rings);select(s.ring,Math.min(s.node,rings[s.ring].length-1));}
function key(event:KeyboardEvent){if((event.ctrlKey||event.metaKey)&&['z','y'].includes(event.key.toLowerCase()))return;if(event.key==='Delete'||event.key==='Backspace'){event.preventDefault();event.stopPropagation();remove();}else if(event.key==='Escape'){event.preventDefault();event.stopPropagation();emit('cancel');}else if(event.key.toLowerCase()==='i'){event.preventDefault();event.stopPropagation();insert();}}
</script>
<template><div ref="root" class="path-node-editor"><svg :viewBox="viewport" :aria-label="zh?'花纹节点预览':localize('Marking node preview')" tabindex="0" @keydown="key" @pointermove="move" @pointerup="end" @pointercancel="end" @lostpointercapture="end"><path v-if="background?.length" :d="backgroundPath??path(background)" class="pattern-context" fill-rule="evenodd"/><path :d="shapePath??path(rings)" :fill="color??'#e8a450'" fill-opacity=".35" fill-rule="evenodd" stroke="currentColor" vector-effect="non-scaling-stroke"/><g v-for="(ring,r) in rings" :key="r" :data-ring="r"><circle v-for="(p,n) in ring" :key="n" :cx="p.xMm" :cy="p.yMm" :r="radius" :data-node="n" :class="['path-node',{selected:selected?.ring===r&&selected.node===n}]" role="button" tabindex="0" :aria-label="(r?(zh?'孔洞':localize('Hole'))+' '+r:(zh?'外轮廓':localize('Outer contour')))+' · '+(zh?'节点':localize('Node'))+' '+(n+1)" :aria-pressed="selected?.ring===r&&selected.node===n" @pointerdown.stop="down($event,r,n)" @keydown.enter.prevent="select(r,n)" @keydown.space.prevent="select(r,n)" @focus="select(r,n)"/></g></svg><div class="node-actions"><span role="status">{{selected?(selected.ring?(zh?'孔洞':localize('Hole'))+' '+selected.ring:(zh?'外轮廓':localize('Outer contour')))+' · '+(zh?'节点':localize('Node'))+' '+(selected.node+1):(zh?'点击圆点选中，拖动调整':localize('Click a node to select; drag to adjust'))}}</span><template v-if="topology!==false"><button :disabled="disabled||!selected||rings[selected.ring].length>=2000" @click="insert">{{zh?'选中点后插入':localize('Insert after selected')}}</button><button :disabled="disabled||!selected||rings[selected.ring].length<=3" @click="remove">{{zh?'删除选中节点':localize('Delete selected node')}}</button></template></div></div></template>
<style scoped>.path-node-editor{width:100%;min-width:0}.path-node-editor svg{width:100%;height:250px;background:var(--model-canvas,#f4f1e9);border:1px solid var(--border,#aaa);border-radius:6px;touch-action:none;user-select:none;color:var(--text,#334)}.pattern-context{fill:#b9bec6;fill-opacity:.14;stroke:#8a8f99;stroke-width:1;vector-effect:non-scaling-stroke}.path-node{fill:#fff;stroke:#b35e12;stroke-width:2;vector-effect:non-scaling-stroke;cursor:grab}.path-node.selected{fill:#f28a22;stroke:#182c44;stroke-width:3}.path-node:focus{outline:none;stroke:#182c44;stroke-width:3}.node-actions{display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:8px 0}.node-actions span{flex:1;min-width:140px}</style>
